#!/usr/bin/env bash
# scripts/verify.sh: the single answer to "is this change OK?"
#
# Run by you, the git pre-commit hook, and every agent (Claude Code and Antigravity):
#   bash scripts/verify.sh fast   # < ~30 s, no test suites: lint, format, types, staged-file checks
#   bash scripts/verify.sh full   # everything: fast + tests, build, analysis, migrations, validate
# Exit codes: 0 ok (INCOMPLETE still exits 0, so read the last line), 1 a check failed, 3 full ran no checks at all (not green).
#
# Generated by the agent-team init-project skill. Edit freely; it's your project's script.
# Helpers:
#   step "<label>" <command...>   run a check and record a failure without stopping
#   staged <pathspec...>          list staged added/modified files (for fast, per-file checks)
#   have <tool-or-path>           true if the tool is installed / the path is executable; prints SKIPPED if not
#   skip "<label>"                record a check that could not run (shown in the final line, never silent)

set -o pipefail
MODE="${1:-full}"
case "$MODE" in fast|full) ;; *) echo "usage: verify.sh [fast|full]" >&2; exit 64 ;; esac
ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
cd "$ROOT" || exit 1

# Ensure agent-team managed tools (~/.agent-team/bin) are in PATH
if [ -d "$HOME/.agent-team/bin" ]; then
  case ":$PATH:" in *":$HOME/.agent-team/bin:"*) ;; *) PATH="$HOME/.agent-team/bin:$PATH" ;; esac
fi

FAILED=""; SKIPPED=""; RAN=0
step() {
  local label="$1"; shift
  printf '\n> %s\n' "$label"; RAN=$((RAN + 1))
  if "$@"; then printf 'ok  %s\n' "$label"; else printf 'FAIL %s\n' "$label"; FAILED="$FAILED, $label"; fi
}
staged() { git diff --cached --name-only --diff-filter=ACMR -- "$@"; }
skip() {   # a check that could not run: never silent
  case "$SKIPPED," in *", $1,"*) return 0 ;; esac
  printf 'SKIPPED %s\n' "$1" >&2; SKIPPED="$SKIPPED, $1"
}
have() { if command -v "$1" >/dev/null 2>&1 || [ -x "$1" ]; then return 0; fi; skip "$1 (not installed)"; return 1; }

# ---------------------------------------------------------------- FAST ----
fast_checks() {
  if [ -f "scripts/check-meta.mjs" ]; then
    step "check-meta" node scripts/check-meta.mjs
  fi
  if [ -f "scripts/check-yaml.mjs" ]; then
    step "check-yaml" node scripts/check-yaml.mjs
  fi
  if [ -f "scripts/check-asmdef.mjs" ]; then
    step "check-asmdef" node scripts/check-asmdef.mjs
  fi
  if have actionlint; then
    step "actionlint" actionlint
  fi
}

# ---------------------------------------------------------------- FULL ----
full_checks() {
  if [ -n "$UNITY_PATH" ] && [ -x "$UNITY_PATH" ]; then
    step "Unity EditMode tests" "$UNITY_PATH" -batchmode -nographics -projectPath . -runTests -testPlatform EditMode -testResults .pipeline/unity-EditMode.xml -logFile .pipeline/unity-EditMode.log
    step "Unity PlayMode tests" "$UNITY_PATH" -batchmode -nographics -projectPath . -runTests -testPlatform PlayMode -testResults .pipeline/unity-PlayMode.xml -logFile .pipeline/unity-PlayMode.log
  else
    skip "Unity batchmode tests (UNITY_PATH not set)"
  fi
}

fast_checks
if [ "$MODE" = "full" ]; then full_checks; fi

if [ -n "$FAILED" ]; then
  printf '\nverify %s: FAILED (%s)\n' "$MODE" "${FAILED#, }"
  exit 1
fi
if [ -n "$SKIPPED" ]; then
  printf '\nverify %s: INCOMPLETE. %d checks passed, NOT VERIFIED (skipped): %s\n' "$MODE" "$RAN" "${SKIPPED#, }"
  exit 0
fi
if [ "$RAN" -eq 0 ]; then
  printf '\nverify %s: NO CHECKS RAN. Nothing is configured yet; fill fast_checks/full_checks (init-project does this).\n' "$MODE"
  # "full" is the done-gate: a run that checked nothing must not look green. "fast" (the pre-commit hook) stays quiet so a new repo can commit.
  if [ "$MODE" = "full" ]; then exit 3; fi
  exit 0
fi
printf '\nverify %s: OK (%d checks)\n' "$MODE" "$RAN"
